# ----------------------------------------------------------------------------
#       The grammar a spec writes.
# ----------------------------------------------------------------------------

@dataclasses.dataclass(frozen=True)
class Option:
    """One option. values=None is a flag; otherwise each value is tried.

    attached says how a value is written: False for "-n 2", True for "-n2"
    (or "--width=2"), None for both shapes in turn. repeat allows the option
    more than once in a random case, the way -e PATTERN is repeated."""
    spell: str
    values: tuple = None
    attached: bool = False
    repeat: bool = False
    weight: int = 1

    def forms(self):
        if self.values is None:
            return ((self.spell,),)
        out = []
        for value in self.values:
            shapes = (self.attached,) if self.attached is not None else (False, True)
            for attached in shapes:
                if attached:
                    glue = "=" if self.spell.startswith("--") else ""
                    out.append((self.spell + glue + value,))
                else:
                    out.append((self.spell, value))
        return tuple(out)


@dataclasses.dataclass(frozen=True)
class Utility:
    """The surface of one program.

    operands is a tuple of alternatives; each alternative is the tuple of
    words placed after the options. Words name files in the fixture set by
    their fixture path. stdin is the tuple of INPUTS names fed in turn.
    stderr is "loose" (both said something or neither), "exact" (byte for
    byte after sandbox paths are replaced) or "ignore". valid prunes an argv
    that cannot mean anything, so the budget is not spent on both tools
    rejecting the same nonsense. normalize(channel, data) rewrites both sides
    before comparison, for a column that is legitimately unstable.
    """
    name: str
    options: tuple = ()
    operands: tuple = ((),)
    stdin: tuple = ("text",)
    fixture: str = "basic"
    stderr: str = "loose"
    normalize: object = None
    valid: object = None
    timeout: float = 5.0
    reference: str = None
    env: tuple = ()
    max_flags: int = 4
    # For a program reached through a shell: modes to run in, and script(argv,
    # stdin_name) building the program text around the generated words.
    modes: tuple = ()
    script: object = None
    # Extra deterministic cases beyond the grammar: a tuple of argv tuples.
    extra: tuple = ()

    def key(self):
        return self.name


@dataclasses.dataclass
class Case:
    domain: str
    utility: str
    argv: list
    stdin: str = "text"
    fixture: str = "basic"
    mode: str = None
    family: str = None
    input_kind: str = "command"
    tier: str = "grammar"

    def identity(self):
        material = json.dumps([self.domain, self.utility, self.argv, self.stdin,
                               self.fixture, self.mode, self.input_kind],
                              separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(material.encode()).hexdigest()[:16]

    def as_dict(self):
        return dataclasses.asdict(self)

    def words(self):
        return " ".join(shlex.quote(word) for word in self.argv)


# ----------------------------------------------------------------------------
#       Walking the grammar.
# ----------------------------------------------------------------------------

def covering_array(parameters, strength, rng):
    """Rows over parameter value indexes so every strength-tuple appears.

    Greedy: each new row starts as the best of a handful of seeded candidates
    by the number of still-uncovered tuples it hits, then is improved one
    column at a time, re-scoring only the column combinations that column
    takes part in. Deterministic for a seed, and small -- a dozen options
    with two values each cover pairwise in about fifteen rows, thirty
    three-valued options cover three-wise in about a hundred and twenty,
    where the products are thousands and millions."""
    sizes = [len(values) for values in parameters]
    if not sizes or strength < 1:
        return []
    strength = min(strength, len(sizes))
    # A program whose widest three parameters multiply into the thousands
    # has a three-wise cover of tens of thousands of tuples, and the greedy
    # builder spends hours on it. Those programs are covered pairwise; the
    # random tier is what reaches deeper into them.
    if strength > 2:
        widest = sorted(sizes, reverse=True)[:3]
        if widest[0] * widest[1] * widest[2] > 4000:
            strength = 2
    combos = list(itertools.combinations(range(len(sizes)), strength))
    uncovered = {c: set(itertools.product(*(range(sizes[i]) for i in c))) for c in combos}
    by_column = {i: [c for c in combos if i in c] for i in range(len(sizes))}
    remaining = sum(len(tuples) for tuples in uncovered.values())

    def hits(row, chosen):
        return sum(1 for c in chosen if tuple(row[i] for i in c) in uncovered[c])

    rows = []
    while remaining:
        best, best_hits = None, -1
        for _ in range(8):
            row = [rng.randrange(size) for size in sizes]
            score = hits(row, combos)
            if score > best_hits:
                best, best_hits = row, score
        for column in rng.sample(range(len(sizes)), len(sizes)):
            chosen = by_column[column]
            current = hits(best, chosen)
            for value in range(sizes[column]):
                if value == best[column]:
                    continue
                trial = list(best)
                trial[column] = value
                score = hits(trial, chosen)
                if score > current:
                    best, current = trial, score
        if hits(best, combos) == 0:
            # Nothing random reached the last tuples: take one directly.
            for c in combos:
                if uncovered[c]:
                    values = next(iter(sorted(uncovered[c])))
                    for i, v in zip(c, values):
                        best[i] = v
                    break
        for c in combos:
            key = tuple(best[i] for i in c)
            if key in uncovered[c]:
                uncovered[c].discard(key)
                remaining -= 1
        rows.append(best)
    return rows


def parameters_of(utility):
    """Each option becomes a parameter whose first value is 'absent'."""
    parameters = []
    for option in utility.options:
        parameters.append(((),) + option.forms())
    parameters.append(tuple(utility.operands))
    parameters.append(tuple(utility.stdin))
    return parameters


def assemble(utility, row, parameters):
    words = []
    count = len(utility.options)
    for index in range(count):
        words.extend(parameters[index][row[index]])
    operands = parameters[count][row[count]]
    stdin = parameters[count + 1][row[count + 1]]
    return list(words) + list(operands), stdin


def grammar_cases(domain, utility, budget, rng):
    """Singles, pairwise, the extra list, then the seeded deeper tier."""
    parameters = parameters_of(utility)
    count = len(utility.options)
    seen = set()

    def emit(argv, stdin, tier):
        if utility.valid and not utility.valid(argv):
            return
        case = Case(domain, utility.name, argv, stdin, utility.fixture, tier=tier)
        key = case.identity()
        if key in seen:
            return
        seen.add(key)
        yield case

    # Nothing at all, then every operand and input shape with no options.
    for operands in utility.operands:
        for stdin in utility.stdin:
            yield from emit(list(operands), stdin, "singles")
    # Every option form alone, on the first operand shape and input.
    for index in range(count):
        for form in parameters[index][1:]:
            yield from emit(list(form) + list(utility.operands[0]), utility.stdin[0], "singles")
    #       A letter and a word the program does not have, asked of every
    #       program rather than of the few whose grammar happens to spell
    #       one. Twenty-one of twenty-one were a line short of the reference
    #       here -- none of them said where to look next -- and no grammar
    #       had ever handed any of them an option that is not there.
    for absent in (["--bogus-option"], ["-\u00f8"], ["--"], ["-"]):
        yield from emit(absent + list(utility.operands[0]), utility.stdin[0], "singles")
    for argv in utility.extra:
        yield from emit(list(argv), utility.stdin[0], "extra")
    if budget == "singles":
        return
    # Triples only where the covering array stays tractable: past two dozen
    # parameters, or where the three largest of them multiply past a few
    # thousand, choosing strength-3 rows costs minutes each. The full
    # budget's deeper random tier already reaches those grammars.
    widest = sorted((len(values) for values in parameters), reverse=True)[:3]
    product = 1
    for size in widest:
        product *= size
    strength = 3 if budget == "full" and len(parameters) <= 24 and product <= 4000 else 2
    for row in covering_array(parameters, strength, random.Random(rng.random())):
        argv, stdin = assemble(utility, row, parameters)
        yield from emit(argv, stdin, "pairs" if strength == 2 else "triples")
    if budget == "full" and count and count <= 10:
        flags = [i for i, option in enumerate(utility.options) if option.values is None]
        for mask in range(1 << len(flags)):
            argv = []
            for bit, index in enumerate(flags):
                if mask >> bit & 1:
                    argv.extend(parameters[index][1])
            for operands in utility.operands:
                yield from emit(argv + list(operands), utility.stdin[0], "powerset")
    depth = {"quick": 2, "default": 4, "full": 12}[budget]
    for _ in range(depth * max(4, count * 2)):
        chosen = []
        for index in range(count):
            option = utility.options[index]
            if rng.random() < 0.5 * option.weight:
                chosen.append(rng.choice(parameters[index][1:]))
                if option.repeat and rng.random() < 0.3:
                    chosen.append(rng.choice(parameters[index][1:]))
        rng.shuffle(chosen)
        chosen = chosen[:utility.max_flags + 2]
        argv = [word for form in chosen for word in form]
        argv += list(rng.choice(utility.operands))
        yield from emit(argv, rng.choice(utility.stdin), "random")


def family_cases(domain, families, budget, seed):
    """rng-driven generators: each yields (family, modes, script)."""
    counts = {"singles": 24, "quick": 48, "default": 96, "full": 512}
    per = counts[budget]
    for name, generator in families:
        rng = random.Random(int.from_bytes(hashlib.sha256(
            f"{seed}:{name}".encode()).digest()[:8], "little"))
        seen = set()
        made = 0
        attempts = 0
        while made < per and attempts < per * 4:
            attempts += 1
            family, modes, script = generator(rng)
            for mode in modes:
                case = Case(domain, "shell", ["-c", script], "empty", "shell",
                            mode=mode, family=family, tier="family")
                key = case.identity()
                if key in seen:
                    continue
                seen.add(key)
                made += 1
                yield case


def shell_grammar_cases(domain, utility, budget, rng):
    """A builtin's grammar, wrapped into a script by the spec, per mode."""
    for case in grammar_cases(domain, utility, budget, rng):
        script = utility.script(case.argv, case.stdin)
        for mode in utility.modes:
            yield Case(domain, "shell", ["-c", script], case.stdin, "shell",
                       mode=mode, family=utility.name, tier=case.tier)


# ----------------------------------------------------------------------------
#       Running one case both ways.
# ----------------------------------------------------------------------------

def _limits():
    resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
    resource.setrlimit(resource.RLIMIT_FSIZE, (OUTPUT_LIMIT * 8, OUTPUT_LIMIT * 8))
    resource.setrlimit(resource.RLIMIT_CPU, (4, 4))
    resource.setrlimit(resource.RLIMIT_NOFILE, (256, 256))


def write_fixture(directory, fixture):
    """Entries: bytes, ("link", target[, stamp]), ("dir"[, mode[, stamp]]),
    ("mode", bytes, mode[, stamp]) or ("hard", source). A stamp is an epoch
    or an (atime, mtime) pair, so a listing's dates and a walk's ages are the
    same on both runs; "." names the directory itself. Stamps and directory
    modes are applied last, deepest first: making an entry moves its
    directory's time, and a directory without search permission hides what
    is below it."""
    later = []
    for name, contents in FIXTURES[fixture].items():
        path = directory / name
        path.parent.mkdir(parents=True, exist_ok=True)
        if isinstance(contents, tuple):
            kind = contents[0]
            if kind == "link":
                path.symlink_to(contents[1])
                later.append((path, None, contents[2] if len(contents) > 2 else None))
            elif kind == "dir":
                path.mkdir(exist_ok=True)
                later.append((path, contents[1] if len(contents) > 1 else None,
                              contents[2] if len(contents) > 2 else None))
            elif kind == "mode":
                path.write_bytes(contents[1])
                path.chmod(contents[2])
                later.append((path, None, contents[3] if len(contents) > 3 else None))
            elif kind == "hard":
                os.link(directory / contents[1], path)
        else:
            path.write_bytes(contents)
            path.chmod(0o644)
    for path, mode, stamp in sorted(later, key=lambda item: -len(item[0].parts)):
        if stamp is not None:
            times = (stamp, stamp) if isinstance(stamp, int) else tuple(stamp)
            os.utime(path, times, follow_symlinks=False)
        if mode is not None:
            path.chmod(mode)


def effects(directory):
    result = {}
    now = time.time()
    for path in sorted(directory.rglob("*")):
        name = str(path.relative_to(directory))
        try:
            info = path.lstat()
        except OSError:
            continue
        mode = stat.S_IMODE(info.st_mode)
        # A modification time far from now was set on purpose (touch -d,
        # cp -p, a stamped fixture kept or moved) and is part of the effect;
        # one near now is only when the run happened.
        stamp = int(info.st_mtime)
        deliberate = [stamp] if abs(stamp - now) > 60 else []
        if stat.S_ISLNK(info.st_mode):
            result[name] = ["link", os.readlink(path)] + deliberate
        elif stat.S_ISDIR(info.st_mode):
            result[name] = ["directory", mode] + deliberate
        elif stat.S_ISREG(info.st_mode):
            try:
                digest = hashlib.sha256(path.read_bytes()).hexdigest()
            except OSError:
                digest = "unreadable"
            result[name] = ["file", mode, info.st_size, digest] + deliberate
        else:
            result[name] = ["special", info.st_mode] + deliberate
    return result


class Runner:
    """Both programs in the same recreated directory, one after the other."""

    def __init__(self, farm, root, emulator=None, locale="C"):
        self.farm = Path(farm).resolve() if farm else None
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)
        self.emulator = emulator
        self.locale = locale
        self.names = self.root / "names"
        self.shell = None
        if self.farm:
            self.shell = self.resolve_shell()
        self.path = [p for p in os.environ.get("PATH", "/usr/bin:/bin").split(":")
                     if p and (not self.farm or Path(p).resolve() != self.farm)]

    def resolve_shell(self):
        for probe in ("cat", "echo", "ls", "sh"):
            link = self.farm / probe
            if link.exists():
                target = Path(os.path.realpath(link))
                break
        else:
            target = self.farm.parent / "shell"
        if not target.exists():
            return None
        self.names.mkdir(exist_ok=True)
        for name in ("bash", "sh", "dash"):
            link = self.names / name
            if not link.is_symlink():
                link.symlink_to(target)
        return target

    def reference_for(self, utility, spec):
        if spec is not None and spec.reference:
            return spec.reference
        for directory in self.path:
            candidate = Path(directory) / utility
            if candidate.is_file() and os.access(candidate, os.X_OK):
                return str(candidate)
        return None

    def programs(self, case, spec):
        """(reference argv prefix, candidate argv prefix) or None if absent."""
        if case.mode:
            reference, flags, name = SHELL_MODES[case.mode]
            if not self.shell:
                return None
            return ([reference] + flags, [str(self.names / name)] + flags, name)
        reference = self.reference_for(case.utility, spec)
        candidate = self.farm / case.utility if self.farm else None
        if not reference or not candidate or not candidate.exists():
            return None
        return ([reference], [str(candidate)], case.utility)

    def run_one(self, prefix, argv0, case, spec, worker):
        directory = self.root / f"w{worker}"
        if directory.exists():
            shutil.rmtree(directory, ignore_errors=True)
            if directory.exists():
                # An unreadable directory left behind: make it removable.
                for path in directory.rglob("*"):
                    try:
                        path.chmod(0o700)
                    except OSError:
                        pass
                shutil.rmtree(directory, ignore_errors=True)
        directory.mkdir()
        write_fixture(directory, case.fixture)
        argv = list(prefix) + list(case.argv)
        executable = argv[0]
        argv[0] = argv0
        if case.mode and case.input_kind != "command":
            script = case.argv[1]
            if case.input_kind == "file":
                source = self.root / f"script{worker}"
                source.write_text(script)
                argv = list(prefix) + [str(source)] + list(case.argv[2:])
                argv[0] = argv0
        if self.emulator and prefix[0].startswith(str(self.root)) or \
                (self.emulator and self.farm and prefix[0].startswith(str(self.farm))):
            argv = [self.emulator, "-0", argv0, executable] + argv[1:]
            executable = self.emulator
        environment = {"PATH": ":".join(self.path), "LC_ALL": self.locale,
                       "LANG": self.locale, "TZ": "UTC0", "HOME": str(directory),
                       "TMPDIR": str(directory), "COLUMNS": "80", "LINES": "24",
                       "TERM": "dumb"}
        if spec is not None:
            environment.update(dict(spec.env))
        timeout = spec.timeout if spec is not None else 5.0
        feed = INPUTS[case.stdin] if case.stdin in INPUTS else b""
        if case.mode and case.input_kind == "stdin":
            feed = case.argv[1].encode()
            argv = list(prefix) + list(case.argv[2:])
            argv[0] = argv0
        with tempfile.TemporaryFile(dir=self.root) as out, \
                tempfile.TemporaryFile(dir=self.root) as err, \
                tempfile.TemporaryFile(dir=self.root) as source:
            source.write(feed)
            source.seek(0)
            try:
                process = subprocess.Popen(argv, executable=executable, cwd=directory,
                                           env=environment, stdin=source, stdout=out,
                                           stderr=err, start_new_session=True,
                                           preexec_fn=_limits)
            except OSError as error:
                return {"status": -256, "timeout": False, "stdout": b"",
                        "stderr": str(error).encode(), "effects": {}}
            timed_out = False
            try:
                process.wait(timeout=timeout)
            except subprocess.TimeoutExpired:
                timed_out = True
            finally:
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                process.wait()
            out.seek(0)
            err.seek(0)
            result = {"status": process.returncode, "timeout": timed_out,
                      "stdout": out.read(OUTPUT_LIMIT + 1),
                      "stderr": err.read(OUTPUT_LIMIT + 1),
                      "effects": effects(directory)}
        result["stderr"] = result["stderr"].replace(str(directory).encode(), b"<DIR>")
        result["stdout"] = result["stdout"].replace(str(directory).encode(), b"<DIR>")
        if spec is not None and spec.normalize:
            for channel in ("stdout", "stderr"):
                result[channel] = spec.normalize(channel, result[channel])
        return result

    def pair(self, case, spec, worker=0):
        programs = self.programs(case, spec)
        if programs is None:
            return None, None
        reference, candidate, name = programs
        want = self.run_one(reference, name, case, spec, worker)
        got = self.run_one(candidate, name, case, spec, worker)
        return want, got


def loose_stderr(data):
    return b"said" if data.strip() else b""


def differences(want, got, policy="loose"):
    keys = []
    for key in ("status", "stdout", "effects", "timeout"):
        if want[key] != got[key]:
            keys.append(key)
    if policy == "exact":
        if _stderr_exact(want["stderr"]) != _stderr_exact(got["stderr"]):
            keys.append("stderr")
    elif policy == "loose":
        if loose_stderr(want["stderr"]) != loose_stderr(got["stderr"]):
            keys.append("stderr")
    return tuple(keys)


def _stderr_exact(data):
    # Both tools name themselves; GNU's spelling of its own path is not the
    # utility's behavior. Reduce "/usr/bin/grep: x" and "grep: x" to "x".
    return re.sub(rb"(?m)^(?:/[^\s:]*/)?([A-Za-z0-9_.+-]+): ", rb"\1: ", data)


def signature(want, got, policy):
    return (want["status"], got["status"], differences(want, got, policy))


def shrink(runner, case, spec, want, got, policy):
    """Drop words (or script lines) while the divergence signature holds."""
    target = signature(want, got, policy)
    if case.mode:
        lines = case.argv[1].splitlines(keepends=True)
        attempts = 0
        chunk = max(1, len(lines) // 2)
        while len(lines) > 1 and attempts < 40:
            changed = False
            for start in range(0, len(lines), chunk):
                smaller = lines[:start] + lines[start + chunk:]
                if not smaller:
                    continue
                attempts += 1
                trial = dataclasses.replace(case, argv=["-c", "".join(smaller)] + case.argv[2:])
                left, right = runner.pair(trial, spec)
                if left and not left["timeout"] and not right["timeout"] and \
                        signature(left, right, policy) == target:
                    lines, case, want, got = smaller, trial, left, right
                    changed = True
                    break
            if not changed:
                if chunk == 1:
                    break
                chunk = max(1, chunk // 2)
        return case, want, got
    words = list(case.argv)
    index = 0
    while index < len(words) and len(words) > 1:
        trial_words = words[:index] + words[index + 1:]
        trial = dataclasses.replace(case, argv=trial_words)
        left, right = runner.pair(trial, spec)
        if left and not left["timeout"] and not right["timeout"] and \
                signature(left, right, policy) == target:
            words, want, got = trial_words, left, right
            continue
        index += 1
    return dataclasses.replace(case, argv=words), want, got


# ----------------------------------------------------------------------------
#       The pinned lists.
# ----------------------------------------------------------------------------

#       Reasons are interned: one row in a hundred carrying the same sentence
#       is a hundred copies of it. Rows point into REASONS and get the text
#       back here, so nothing downstream knows the difference.
def _resolved(rows):
    table = globals().get("REASONS", {})
    for row in rows:
        if "reason_id" in row and "reason" not in row:
            row["reason"] = table.get(row["reason_id"], row["reason_id"])
    return rows


def _pins_are_json():
    return PIN_FILE.suffix == ".json"


def _pin_span(text):
    """Where the pinned block sits: the markers on lines of their own, not
    the two constants above that spell them."""
    begin = text.index("\n" + PIN_BEGIN + "\n") + len(PIN_BEGIN) + 2
    end = text.index("\n" + PIN_END, begin)
    return begin, end


def load_rows(which):
    """The pinned rows of one list ("ledger", "regression" or "unstable")."""
    if _pins_are_json():
        rows = json.loads(PIN_FILE.read_text() or "[]") if PIN_FILE.exists() else []
        return _resolved([row for row in rows if row.get("list") == which])
    text = PIN_FILE.read_text()
    begin, end = _pin_span(text)
    block = text[begin:end].strip()
    block = block[len('PINNED = r"""'):] if block.startswith('PINNED = r"""') else block
    block = block[:-3] if block.endswith('"""') else block
    rows = json.loads(block or "[]")
    if not isinstance(rows, list):
        raise SystemExit(f"{PIN_FILE}: pinned rows must be a list")
    return _resolved([row for row in rows if row.get("list") == which])


def save_rows(which, rows):
    """Rewrite the block between the markers with these rows for one list."""
    text = PIN_FILE.read_text() if not _pins_are_json() else ""
    begin, end = _pin_span(text) if not _pins_are_json() else (0, 0)
    others = [row for row in load_rows("ledger") + load_rows("regression")
              + load_rows("unstable") if row.get("list") != which]
    for row in rows:
        row["list"] = which
    merged = sorted(others + rows,
                    key=lambda row: (row.get("list", ""), row.get("domain", ""),
                                     row.get("utility", ""), row.get("option", ""),
                                     row.get("id", "")))
    for row in merged:
        if row.get("reason_id") and \
                row.get("reason") == globals().get("REASONS", {}).get(row["reason_id"]):
            row.pop("reason")
    body = json.dumps(merged, indent=1, ensure_ascii=False, sort_keys=True)
    if _pins_are_json():
        PIN_FILE.write_text(body + "\n")
        return
    text = text[:begin] + 'PINNED = r"""\n' + body + '\n"""' + text[end:]
    PIN_FILE.write_text(text)


def row_case(row):
    case = row["case"]
    return Case(case["domain"], case["utility"], list(case["argv"]), case.get("stdin", "text"),
                case.get("fixture", "basic"), case.get("mode"), case.get("family"),
                case.get("input_kind", "command"), tier="pinned")


def digest(result):
    return {"status": result["status"],
            "stdout": hashlib.sha256(result["stdout"]).hexdigest(),
            "effects": hashlib.sha256(json.dumps(result["effects"], sort_keys=True).encode()).hexdigest()}


def option_words(utility, argv):
    """The words of an argv that are options rather than another option's value.

    A valued option written apart from its value -- ptx -M -O -- makes the
    next word that option's value, and a ledger row keyed on an option must
    not match it there. Without a spec every word is an option, which is what
    the matcher did before."""
    valued = set()
    if utility is not None:
        for option in utility.options:
            if option.values is not None:
                valued.add(option.spell)
    words = []
    skip = False
    for index, word in enumerate(argv):
        if skip:
            skip = False
            continue
        words.append(word)
        if word in valued:
            skip = True
    return words


def option_ledger(rows, case, utility=None):
    """A row keyed by option rather than by case: the whole option is refused."""
    words = option_words(utility, case.argv)
    for row in rows:
        if "option" not in row or row.get("utility") != case.utility:
            continue
        if row.get("domain") not in (None, case.domain):
            continue
        spell = row["option"]
        for word in words:
            if word == spell or (spell.startswith("--") and word.startswith(spell + "=")) \
                    or (not spell.startswith("--") and len(spell) == 2 and word.startswith(spell) and not word.startswith("--")):
                return row
    return None


# ----------------------------------------------------------------------------
#       Loading specs and building the case list.
# ----------------------------------------------------------------------------

def load_spec(domain):
    """The grammar of one domain: inlined below when SPECS exists, else a
    spec_<domain>.py module beside this file while a grammar is being written."""
    specs = globals().get("SPECS")
    if specs is not None and domain in specs:
        utilities, families, checks = specs[domain]
        namespace = type("Spec", (), {})()
        namespace.UTILITIES = utilities
        namespace.FAMILIES = families
        namespace.CHECKS = checks
        return namespace
    if str(HERE) not in sys.path:
        sys.path.append(str(HERE))
    # A spec imports this module by its file name. Run as the program (or
    # as a pool worker's __mp_main__) that name would be a second copy with
    # its own INPUTS and FIXTURES, and what a spec adds to them would be
    # lost. Point the name at the module that is running.
    sys.modules.setdefault("differential", sys.modules[__name__])
    try:
        return importlib.import_module(f"spec_{domain}")
    except ModuleNotFoundError as error:
        if error.name == f"spec_{domain}":
            return None
        raise


def spec_utilities(spec):
    return {utility.name: utility for utility in getattr(spec, "UTILITIES", ())} if spec else {}


def build_cases(domain, spec, budget, seed, selected, modes, families):
    utilities = spec_utilities(spec)
    cases = []
    for name, utility in sorted(utilities.items()):
        if selected and name not in selected:
            continue
        # An input or fixture the spec misspelled would otherwise feed nothing
        # and pass, since both programs would agree about an empty input.
        for stdin in utility.stdin:
            if stdin not in INPUTS:
                raise SystemExit(f"spec_{domain}: {name} names unknown input {stdin!r}")
        if utility.fixture not in FIXTURES:
            raise SystemExit(f"spec_{domain}: {name} names unknown fixture {utility.fixture!r}")
        rng = random.Random(int.from_bytes(hashlib.sha256(
            f"{seed}:{domain}:{name}".encode()).digest()[:8], "little"))
        if utility.modes:
            for case in shell_grammar_cases(domain, utility, budget, rng):
                if not modes or case.mode in modes:
                    cases.append(case)
        else:
            cases.extend(grammar_cases(domain, utility, budget, rng))
    if spec and getattr(spec, "FAMILIES", None) and (not selected or "shell" in selected):
        chosen = [(f.__name__, f) for f in spec.FAMILIES
                  if not families or f.__name__ in families]
        for case in family_cases(domain, chosen, budget, seed):
            if not modes or case.mode in modes:
                cases.append(case)
    return cases, utilities


# ----------------------------------------------------------------------------
#       Parallel execution.
# ----------------------------------------------------------------------------

_worker_runner = None
_worker_specs = None


def _worker_init(farm, root, emulator, locale, domains):
    global _worker_runner, _worker_specs
    _worker_runner = Runner(farm, Path(root) / f"p{os.getpid()}", emulator, locale)
    _worker_specs = {domain: spec_utilities(load_spec(domain)) for domain in domains}


def _worker_run(payload):
    case = Case(**payload)
    spec = _worker_specs.get(case.domain, {}).get(case.family if case.mode else case.utility)
    want, got = _worker_runner.pair(case, spec)
    if want is None:
        return payload, None, None
    return payload, want, got


def serializable(result):
    return {key: (value.hex() if isinstance(value, bytes) else value)
            for key, value in result.items()}


def show(data, limit=160):
    text = data[:limit].decode("utf-8", "backslashreplace").replace("\n", "|")
    return text + ("..." if len(data) > limit else "")


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("farm", nargs="?", type=Path,
                        help="directory of the names our shell answers to")
    parser.add_argument("--domain", action="append", choices=DOMAINS)
    parser.add_argument("--utility", action="append", help="only these programs (or 'shell')")
    parser.add_argument("--family", action="append", help="only these shell families")
    parser.add_argument("--mode", action="append", choices=tuple(SHELL_MODES))
    parser.add_argument("--budget", default=os.environ.get("MW_BUDGET"),
                        choices=("singles", "quick", "default", "full"),
                        help="how deep to walk; the default is the budget the "
                             "domain is gated at (see DOMAIN_BUDGET)")
    parser.add_argument("--seed", type=lambda v: int(v, 0),
                        default=int(os.environ.get("MW_SEED", "0x4d574253"), 0))
    parser.add_argument("--jobs", type=int, default=max(1, (os.cpu_count() or 2) - 1))
    parser.add_argument("--locale", default="C")
    parser.add_argument("--emulator", type=Path)
    parser.add_argument("--input", dest="input_kind", choices=("command", "file", "stdin"),
                        default="command", help="how a shell case is handed its program")
    parser.add_argument("--replay", type=Path, action="append",
                        help="run the case saved in an artifact JSON")
    parser.add_argument("--artifacts", type=Path, default=os.environ.get("MW_ARTIFACTS"))
    parser.add_argument("--shrink", action="store_true")
    parser.add_argument("--max-failures", type=int, default=12,
                        help="distinct failure classes shown per program")
    parser.add_argument("--record", choices=("ledger", "regression", "refresh", "unstable"),
                        help="write every divergence (ledger) or every agreement of the "
                             "cases run (regression) into the pinned list; refresh brings "
                             "existing rows back in line with the tree after a fix landed "
                             "somewhere else; unstable runs the set --repeat times and "
                             "records the cases that contradict themselves")
    parser.add_argument("--repeat", type=int, default=3,
                        help="passes over the set for --record unstable")
    parser.add_argument("--reason", help="the reason written with --record ledger")
    parser.add_argument("--kind", default="deliberate", choices=("deliberate", "bug"))
    parser.add_argument("--no-pinned", action="store_true", help="skip ledger and regressions")
    parser.add_argument("--pins", type=Path, default=os.environ.get("MW_PINS"),
                        help="read and record pinned rows in this JSON file instead of "
                             "the block at the end of this program")
    parser.add_argument("--list", action="store_true", help="print the cases and stop")
    parser.add_argument("--self-test", action="store_true")
    parser.add_argument("--harness", nargs=argparse.REMAINDER,
                        help="run one of the folded standalone checks: --harness NAME [ARGS]")
    args = parser.parse_args(argv)

    if args.self_test:
        return self_test()
    if args.harness is not None:
        entry = globals().get("harness_main")
        if entry is not None:
            return entry(args.harness)
        entry = globals().get("harness_entry")
        if entry is None:
            parser.error("no harness is folded into this file")
        sys.argv = [sys.argv[0]] + args.harness
        return entry()
    if args.pins:
        globals()["PIN_FILE"] = args.pins.resolve()
    if not args.farm and not args.list:
        parser.error("a farm directory is required")
    if args.record == "ledger" and not args.reason:
        parser.error("--record ledger needs --reason")

    domains = args.domain or list(DOMAINS)
    specs = {domain: load_spec(domain) for domain in domains}
    selected = set(args.utility or ())
    modes = set(args.mode or ())
    families = set(args.family or ())

    cases = []
    utilities = {}
    if args.replay:
        for path in args.replay:
            saved = json.loads(path.read_text())
            cases.append(row_case(saved))
        domains = sorted({case.domain for case in cases})
        specs = {domain: load_spec(domain) for domain in domains}
        for domain in domains:
            utilities.update(spec_utilities(specs[domain]))
    else:
        for domain in domains:
            budget = args.budget or DOMAIN_BUDGET.get(domain, "default")
            made, found = build_cases(domain, specs[domain], budget, args.seed,
                                      selected, modes, families)
            cases.extend(made)
            utilities.update(found)
    for case in cases:
        if case.mode:
            case.input_kind = args.input_kind

    ledger = [] if args.no_pinned else load_rows("ledger")
    regressions = [] if args.no_pinned else load_rows("regression")
    unstable_ids = set() if args.no_pinned else {
        row["id"] for row in load_rows("unstable") if "id" in row}
    pinned = {}
    if not args.no_pinned and not args.replay:
        for row in ledger + regressions:
            if "case" not in row or row["case"]["domain"] not in domains:
                continue
            case = row_case(row)
            if selected and (case.family if case.mode else case.utility) not in selected \
                    and case.utility not in selected:
                continue
            if modes and case.mode and case.mode not in modes:
                continue
            pinned[case.identity()] = (row, case)
    generated_ids = {case.identity() for case in cases}
    cases = [case for case in cases if case.identity() not in pinned]
    cases.extend(case for _, case in pinned.values())

    if args.list:
        for case in cases:
            label = f"{case.domain}/{case.family or case.utility}"
            if case.mode:
                label += f"[{case.mode}]"
            print(f"{case.identity()} {label} {case.tier:8} {case.words()}  <{case.stdin}")
        print(f"{len(cases)} cases")
        return 0

    farm = args.farm.resolve(strict=True)
    emulator = str(args.emulator.resolve(strict=True)) if args.emulator else None
    if args.artifacts:
        args.artifacts.mkdir(parents=True, exist_ok=True)

    shown_budget = args.budget or ",".join(
        f"{d}:{DOMAIN_BUDGET.get(d, 'default')}" for d in domains)
    print(f"  differential seed={hex(args.seed)} budget={shown_budget} cases={len(cases)} "
          f"domains={','.join(domains)} jobs={args.jobs}; compares status, stdout, effects and diagnostics")

    passed = collections.Counter()
    total = collections.Counter()
    unstable = collections.Counter()
    absent = collections.Counter()
    invalid = 0
    tiers = collections.Counter()
    failures = collections.defaultdict(collections.Counter)
    shown = collections.Counter()
    to_record = []
    refreshed_gone = []
    refreshed_moved = []
    ledger_rows_by_id = {row["id"]: row for row in ledger if "id" in row}
    regression_ids = {row["id"] for row in regressions if "id" in row}

    def label_of(case):
        name = case.family or case.utility
        return f"{case.domain}/{name}" + (f"[{case.mode}]" if case.mode else "")

    with tempfile.TemporaryDirectory(prefix="differential-") as temporary:
        runner = Runner(farm, Path(temporary) / "main", emulator, args.locale)
        payloads = [case.as_dict() for case in cases]

        def sweep():
            """One pass over every case, in the pool when there is one."""
            if args.jobs > 1 and len(payloads) > 8:
                pool = concurrent.futures.ProcessPoolExecutor(
                    max_workers=args.jobs, initializer=_worker_init,
                    initargs=(str(farm), temporary, emulator, args.locale, domains))
                return pool, pool.map(_worker_run, payloads, chunksize=4)
            _worker_init(str(farm), temporary, emulator, args.locale, domains)
            return None, map(_worker_run, payloads)

        if args.record == "unstable":
            #       A case that answers differently when asked again is
            #       neither an agreement nor a divergence: a pseudo-terminal
            #       interleaves by timing, a namespace is populated as the
            #       kernel pleases. Ask the whole set --repeat times and
            #       record by identity the cases that contradict themselves,
            #       so that afterwards every run counts them the same way
            #       however they happen to fall. Recording is a pass over the
            #       pool, not a serial re-ask in this process.
            first = {}
            wobbled = {}
            for number in range(max(2, args.repeat)):
                pool, results = sweep()
                for payload, want, got in results:
                    case = Case(**payload)
                    key = case.identity()
                    if want is None:
                        continue
                    spec = utilities.get(case.family or case.utility)
                    mark = signature(want, got, spec.stderr if spec else "loose")
                    if key in first:
                        if first[key] != mark:
                            wobbled.setdefault(key, case)
                    else:
                        first[key] = mark
                if pool is not None:
                    pool.shutdown()
                print(f"  pass {number + 1} of {max(2, args.repeat)}: "
                      f"{len(wobbled)} cases have contradicted themselves")
            rows = [] if args.no_pinned else load_rows("unstable")
            already = {row.get("id") for row in rows}
            for key in sorted(wobbled):
                if key in already:
                    continue
                case = wobbled[key]
                rows.append({"list": "unstable", "id": key, "domain": case.domain,
                             "utility": case.family or case.utility,
                             "reason": args.reason or
                             "answers differently when the same case is asked again"})
            save_rows("unstable", rows)
            print(f"  recorded {len(wobbled)} unstable cases; the list now holds {len(rows)}")
            return 0

        executor, results = sweep()
        for payload, want, got in results:
            case = Case(**payload)
            key = case.identity()
            name = case.family or case.utility
            spec = utilities.get(name)
            policy = spec.stderr if spec else "loose"
            tally_key = f"{case.domain}/{name}"
            if want is None:
                absent[tally_key] += 1
                continue
            #       A case whose answer is not determined cannot gate
            #       anything, and cannot be allowed to move a count either
            #       way. Recorded by identity, so every run treats it alike
            #       however it happens to fall this time.
            if key in unstable_ids:
                unstable[tally_key] += 1
                continue
            #       An oracle that timed out or died of a signal answered
            #       nothing, so the case has no answer to agree or disagree
            #       with -- and whether the reference runs out of time
            #       depends on what else the machine is doing. Counted apart
            #       from both columns, like a case that contradicts itself,
            #       so a busy machine cannot move a floor.
            if want["timeout"] or want["status"] < 0:
                invalid += 1
                print(f"  INVALID ORACLE {key} {label_of(case)} status={want['status']} "
                      f"timeout={want['timeout']}: {case.words()}")
                continue
            total[tally_key] += 1
            tiers[case.tier] += 1
            diff = differences(want, got, policy)
            row = ledger_rows_by_id.get(key) or option_ledger(ledger, case, spec)
            if row is not None and "case" in row:
                # A pinned deliberate difference: the answer must hold, and
                # must still differ from the reference.
                if not diff:
                    #       The difference this row recorded is gone. For a bug
                    #       that is the bug being fixed, usually by another
                    #       domain touching shared code, and the row should go.
                    #       For a deliberate policy it means the policy was
                    #       lost, which is a failure whatever the mode.
                    if args.record == "refresh" and row.get("kind") == "bug":
                        #       One observation of agreement is what this has.
                        #       A case that races decides differently the next
                        #       time and the row is then gone for nothing, so
                        #       confirm it before dropping.
                        again, again_got = runner.pair(case, spec)
                        if again and not differences(again, again_got, policy):
                            refreshed_gone.append(row)
                            passed[tally_key] += 1
                            continue
                        print(f"  kept {key} {label_of(case)}: agreed once and differed "
                              f"again, so the row stays")
                        passed[tally_key] += 1
                        continue
                    failures[tally_key][("ledger-agrees",)] += 1
                    print(f"  FAIL {key} {label_of(case)} agrees with the reference now -- "
                          f"remove its ledger row: {case.words()}")
                elif digest(got) != row["candidate"]:
                    if args.record == "refresh":
                        refreshed_moved.append((row, digest(got)))
                        passed[tally_key] += 1
                        continue
                    failures[tally_key][("ledger-drift",)] += 1
                    print(f"  FAIL {key} {label_of(case)} ledger row drifted: {case.words()}")
                    print(f"       pinned {row['candidate']} now {digest(got)}")
                else:
                    passed[tally_key] += 1
                continue
            if row is not None and "option" in row:
                # A refused option: ours must refuse it (nonzero, silent).
                if got["status"] != 0 and not got["stdout"]:
                    passed[tally_key] += 1
                    continue
                if not diff:
                    failures[tally_key][("ledger-option-agrees",)] += 1
                    print(f"  FAIL {key} {label_of(case)} agrees with the reference although "
                          f"the ledger refuses {row['option']}: {case.words()}")
                    continue
            if not diff:
                passed[tally_key] += 1
                if args.record == "regression" and key not in regression_ids:
                    to_record.append((case, want, got))
                continue
            if key in regression_ids:
                diff = diff + ("regression",)
            sig = (want["status"], got["status"], diff)
            failures[tally_key][sig] += 1
            first = failures[tally_key][sig] == 1
            original = case
            if args.shrink and first and not want["timeout"] and not got["timeout"]:
                case, want, got = shrink(runner, case, spec, want, got, policy)
            if first and shown[tally_key] < args.max_failures:
                shown[tally_key] += 1
                print(f"  FAIL {key} {label_of(case)} tier={case.tier} differences={diff}")
                print(f"       {case.utility if not case.mode else case.mode} {case.words()}  <{case.stdin}  fixture={case.fixture}")
                print(f"       reference status={want['status']} stdout={show(want['stdout'])!r} stderr={show(want['stderr'], 100)!r}")
                print(f"       candidate status={got['status']} stdout={show(got['stdout'])!r} stderr={show(got['stderr'], 100)!r}")
                if "effects" in diff:
                    changed = sorted(set(want["effects"]) ^ set(got["effects"]) |
                                     {k for k in want["effects"] if k in got["effects"]
                                      and want["effects"][k] != got["effects"][k]})
                    print(f"       effects differ at {changed[:8]}")
            elif shown[tally_key] >= args.max_failures and first:
                shown[tally_key] += 1
                if shown[tally_key] == args.max_failures + 1:
                    print(f"  ... more distinct failures in {tally_key} not shown")
            if args.artifacts:
                artifact = {"id": key, "case": original.as_dict(), "shrunk": case.as_dict(),
                            "reference": serializable(want), "candidate": serializable(got),
                            "differences": diff}
                (args.artifacts / f"{key}.json").write_text(json.dumps(artifact, indent=1) + "\n")
            if args.record == "ledger":
                to_record.append((original, want, got))
        if executor:
            executor.shutdown()

    if args.record == "refresh":
        gone = {id(row) for row in refreshed_gone}
        moved = {id(row): answer for row, answer in refreshed_moved}
        kept = []
        for row in ledger:
            if id(row) in gone:
                continue
            if id(row) in moved:
                #       The answer moved, so the row still records a real
                #       difference -- but its reason was written about the old
                #       answer and nothing here can tell whether it still
                #       describes this one. Say so in the row rather than let
                #       a stale sentence pass for a checked one.
                row["candidate"] = moved[id(row)]
                row["reason_unverified"] = ("the answer moved after a change elsewhere; "
                                            "this reason was not re-checked against it")
            kept.append(row)
        if refreshed_gone or refreshed_moved:
            save_rows("ledger", kept)
        print(f"  refreshed the ledger: {len(refreshed_gone)} rows dropped because the "
              f"difference is gone, {len(refreshed_moved)} re-pinned because the answer moved")
        for row in refreshed_moved:
            print(f"    moved  {row[0].get('id')} {row[0].get('domain')}/{row[0].get('utility')}"
                  f"  {row[0].get('reason', '')[:60]}")

    if args.record in ("ledger", "regression") and to_record:
        rows = ledger if args.record == "ledger" else regressions
        known = {row.get("id") for row in rows}
        added = 0
        for case, want, got in to_record:
            key = case.identity()
            if key in known:
                continue
            row = {"id": key, "domain": case.domain, "utility": case.family or case.utility,
                   "case": case.as_dict()}
            if args.record == "ledger":
                row["reason"] = args.reason
                row["kind"] = args.kind
                row["candidate"] = digest(got)
                row["reference"] = digest(want)
            rows.append(row)
            known.add(key)
            added += 1
        save_rows(args.record, rows)
        print(f"  recorded {added} rows into {args.record}")

    if not args.replay:
        for domain in domains:
            for check in getattr(specs.get(domain), "CHECKS", ()):
                if selected and check.__name__ not in selected:
                    continue
                key = f"{domain}/{check.__name__}"
                won, count, notes = check(str(farm))
                passed[key] += won
                total[key] += count
                for note in notes:
                    failures[key][("check",)] += 1
                    print(f"  FAIL {key}: {note}")

    #       Whether this run is the one floors are recorded against: a
    #       narrowed run walks a different set and cannot be held to them.
    whole_run = not (args.replay or selected or modes or families or args.budget)

    for key in sorted(set(total) | set(absent)):
        line = f"  {key:28} {passed[key]} of {total[key]}"
        if unstable[key]:
            line += f"  ({unstable[key]} recorded unstable, counted in neither column)"
        if absent[key]:
            line += f"  ({absent[key]} NOT RUN -- no reference or candidate program)"
        print(line)
        #       The runner adds every row up and calls a shortfall a
        #       failure. That is right for a domain meant to agree on
        #       everything, and wrong for one held to a floor, where the
        #       floor is the assertion and these numbers are the evidence
        #       for it. So a floored domain's programs are printed and not
        #       tallied, and the floor writes the one row it is owed.
        floored_here = whole_run and key.split("/")[0] in DOMAIN_FLOOR

        if os.environ.get("TEST_TALLY") and total[key] and not floored_here:
            with open(os.environ["TEST_TALLY"], "a") as tally:
                tally.write(f"{key.replace('/', '-')} {passed[key]} {total[key]}\n")
    all_passed = sum(passed.values())
    all_total = sum(total.values())

    #       A domain whose pinning is unfinished is held to the count it
    #       reached. Agreeing on more is progress and says so; agreeing on
    #       fewer is a regression inside the gap and fails.
    floored = True
    if whole_run:
        for domain in domains:
            floor = DOMAIN_FLOOR.get(domain)
            if not floor:
                continue
            agreed = sum(count for key, count in passed.items()
                         if key.startswith(domain + "/"))
            ran = sum(count for key, count in total.items()
                      if key.startswith(domain + "/"))
            want, of, slack, why = floor

            #       The one row the floor is owed, in place of the programs
            #       it stands for: it holds, or it does not.
            if os.environ.get("TEST_TALLY"):
                with open(os.environ["TEST_TALLY"], "a") as tally:
                    tally.write(f"{domain}-floor {1 if agreed >= want else 0} 1\n")

            if agreed < want:
                floored = False
                print(f"  FLOOR {domain}: {agreed} of {ran} agree, below the {want} of {of} "
                      f"this domain is held to -- a regression inside a known gap")
                print(f"        the gap is {why}")
            elif agreed > want + slack:
                #       Past what the floor allows for the cases that still
                #       flip, so it is a gain rather than a good day.
                print(f"  floor {domain}: {agreed} of {ran} agree, {agreed - want} above the "
                      f"{want} of {of} recorded, which is more than the {slack} it allows "
                      f"for -- raise the floor in DOMAIN_FLOOR to keep the gain")
            else:
                print(f"  floor {domain}: {agreed} of {ran}, within the {slack} "
                      f"the recorded {want} allows for")
    distinct = sum(len(v) for v in failures.values())
    print(f"  tiers: " + " ".join(f"{k}={v}" for k, v in sorted(tiers.items())))
    print(f"  differential {all_passed} of {all_total}; failure classes={distinct}, "
          f"invalid oracles={invalid}, unstable={sum(unstable.values())}, "
          f"not run={sum(absent.values())}")
    if not all_total:
        print("  differential NOT RUN -- no case had both programs")
        return 2
    if not floored:
        return 1
    #       Cases inside a floored domain are not counted against the run;
    #       the floor above is what holds them.
    unfloored = sum(count for key, count in total.items()
                    if key.split("/")[0] not in DOMAIN_FLOOR)
    unfloored_passed = sum(count for key, count in passed.items()
                           if key.split("/")[0] not in DOMAIN_FLOOR)
    if args.replay or selected or modes or families or args.budget:
        return 1 if all_passed != all_total or invalid else 0
    return 1 if unfloored_passed != unfloored else 0


# ----------------------------------------------------------------------------
#       The oracle checked against deliberately wrong subjects.
# ----------------------------------------------------------------------------

def self_test():
    import unittest

    class Oracle(unittest.TestCase):
        def setUp(self):
            self.temporary = tempfile.TemporaryDirectory(prefix="differential-self-")
            self.root = Path(self.temporary.name)
            self.system = self.root / "system"
            self.farm = self.root / "farm"
            self.system.mkdir()
            self.farm.mkdir()
            self.script(self.system / "echoer", "#!/bin/sh\nprintf '%s\\n' \"$@\"; cat\n")
            self.script(self.farm / "echoer", "#!/bin/sh\nprintf '%s\\n' \"$@\"; cat\n")
            self.script(self.system / "maker", "#!/bin/sh\nprintf made > out; exit 3\n")
            self.script(self.farm / "maker", "#!/bin/sh\nprintf made > out; exit 3\n")
            self.script(self.farm / "wrong", "#!/bin/sh\nprintf wrong\n")
            self.script(self.system / "wrong", "#!/bin/sh\nprintf right\n")
            self.script(self.farm / "quiet", "#!/bin/sh\nexit 0\n")
            self.script(self.system / "quiet", "#!/bin/sh\nexit 1\n")
            self.script(self.farm / "chatty", "#!/bin/sh\necho oops >&2\n")
            self.script(self.system / "chatty", "#!/bin/sh\nexit 0\n")
            self.script(self.farm / "sleeper", "#!/bin/sh\nsleep 5\n")
            self.script(self.system / "sleeper", "#!/bin/sh\nexit 0\n")
            self.script(self.farm / "dawdler", "#!/bin/sh\nexit 0\n")
            self.script(self.system / "dawdler", "#!/bin/sh\nsleep 5\n")
            self.script(self.farm / "flagged", "#!/bin/sh\nfor a; do case $a in -z) exit 2;; esac; done; printf ok\n")
            self.script(self.system / "flagged", "#!/bin/sh\nprintf ok\n")
            self.script(self.farm / "effect", "#!/bin/sh\nprintf x > a.txt\n")
            self.script(self.system / "effect", "#!/bin/sh\nprintf y > a.txt\n")
            self.old_path = os.environ.get("PATH")
            os.environ["PATH"] = f"{self.system}:/usr/bin:/bin"
            # The inner runs must not write their rows into the suite's tally,
            # nor read the caller's pinned rows in place of their own fixtures.
            self.old_tally = os.environ.pop("TEST_TALLY", None)
            self.old_pins = os.environ.pop("MW_PINS", None)
            self.runner = Runner(self.farm, self.root / "run")

        def tearDown(self):
            os.environ["PATH"] = self.old_path
            if self.old_tally is not None:
                os.environ["TEST_TALLY"] = self.old_tally
            if self.old_pins is not None:
                os.environ["MW_PINS"] = self.old_pins
            self.temporary.cleanup()

        def script(self, path, text):
            path.write_text(text)
            path.chmod(0o755)

        def pair(self, utility, argv, stdin="text", fixture="basic"):
            case = Case("text", utility, argv, stdin, fixture)
            return case, self.runner.pair(case, None)

        def test_same_programs_agree_including_effects_and_input(self):
            _, (want, got) = self.pair("echoer", ["-a", "b c"], "fields")
            self.assertEqual(differences(want, got), ())
            self.assertEqual(want["stdout"], b"-a\nb c\n" + INPUTS["fields"])
            _, (want, got) = self.pair("maker", [])
            self.assertEqual(differences(want, got), ())
            self.assertEqual(want["status"], 3)
            self.assertEqual(got["effects"]["out"][2], 4)

        def test_directory_is_recreated_between_cases(self):
            self.pair("maker", [])
            _, (want, got) = self.pair("echoer", [])
            self.assertNotIn("out", got["effects"])
            self.assertIn("dir/sub/deep", got["effects"])
            self.assertEqual(got["effects"]["link"], ["link", "a.txt"])

        def test_wrong_subject_cannot_pass_each_channel(self):
            _, (want, got) = self.pair("wrong", [])
            self.assertEqual(differences(want, got), ("stdout",))
            _, (want, got) = self.pair("quiet", [])
            self.assertEqual(differences(want, got), ("status",))
            _, (want, got) = self.pair("effect", [])
            self.assertEqual(differences(want, got), ("effects",))
            _, (want, got) = self.pair("chatty", [])
            self.assertEqual(differences(want, got, "loose"), ("stderr",))
            self.assertEqual(differences(want, got, "ignore"), ())
            self.assertIn("stderr", differences(want, got, "exact"))

        def test_exact_stderr_drops_only_the_program_path(self):
            self.assertEqual(_stderr_exact(b"/usr/bin/grep: bad\ngrep: x\n"),
                             b"grep: bad\ngrep: x\n")
            self.assertNotEqual(_stderr_exact(b"grep: bad\n"), _stderr_exact(b"grep: worse\n"))

        #       These two are the only tests here that a clock decides, and
        #       the sleeper they run sleeps for five seconds. The budget sits
        #       well under that so the timeout is certain, and well over what
        #       a program that does nothing costs on a machine that is busy,
        #       so the other side is certain too.
        def test_candidate_timeout_is_a_divergence(self):
            spec = Utility("sleeper", timeout=2.5)
            case = Case("text", "sleeper", [])
            want, got = self.runner.pair(case, spec)
            self.assertTrue(got["timeout"])
            self.assertIn("timeout", differences(want, got))

        def test_reference_timeout_is_counted_in_neither_column(self):
            """An oracle that ran out of time answered nothing, so the case
            has nothing to agree or disagree with -- and whether it runs out
            depends on what else the machine is doing. It must leave the
            denominator, or a busy machine moves a floor."""
            spec = Utility("dawdler", timeout=2.5)
            case = Case("text", "dawdler", [])
            want, got = self.runner.pair(case, spec)
            self.assertTrue(want["timeout"])
            saved = globals().get("SPECS")
            globals()["SPECS"] = {"text": ((spec,), (), ())}
            import io
            import contextlib
            written = io.StringIO()
            try:
                with contextlib.redirect_stdout(written):
                    main([str(self.farm), "--domain", "text", "--budget", "singles",
                          "--jobs", "1", "--no-pinned"])
            finally:
                globals()["SPECS"] = saved
            report = written.getvalue()
            self.assertIn("INVALID ORACLE", report)
            #       However many cases the walk makes of this one program --
            #       the options it does not have are asked of every program
            #       -- every one of them has an oracle that never answered,
            #       so the denominator is empty and the count is them all.
            made = int(re.search(r"cases=(\d+)", report).group(1))
            self.assertIn(f"invalid oracles={made}", report)
            self.assertIn("differential 0 of 0", report)

        def test_missing_reference_is_reported_not_passed(self):
            case = Case("text", "nowhere-such", [])
            self.assertEqual(self.runner.pair(case, None), (None, None))

        def test_covering_array_covers_every_pair(self):
            parameters = [(0, 1), (0, 1, 2), (0, 1), (0, 1, 2, 3), (0, 1)]
            rows = covering_array([tuple(range(len(p))) for p in parameters], 2, random.Random(7))
            for a, b in itertools.combinations(range(len(parameters)), 2):
                for va in range(len(parameters[a])):
                    for vb in range(len(parameters[b])):
                        self.assertTrue(any(row[a] == va and row[b] == vb for row in rows),
                                        (a, b, va, vb))
            self.assertLess(len(rows), 12 * 4)
            again = covering_array([tuple(range(len(p))) for p in parameters], 2, random.Random(7))
            self.assertEqual(rows, again)

        def test_grammar_walk_is_deterministic_and_complete_for_singles(self):
            spec = Utility("flagged", options=(Option("-a"), Option("-z"), Option("-n", ("1", "2"), None)),
                           operands=((), ("a.txt",)), stdin=("text", "empty"))
            first = list(grammar_cases("text", spec, "default", random.Random(1)))
            second = list(grammar_cases("text", spec, "default", random.Random(1)))
            self.assertEqual([c.identity() for c in first], [c.identity() for c in second])
            words = {tuple(c.argv) for c in first}
            for single in (("-a",), ("-z",), ("-n", "1"), ("-n2",), ("a.txt",), ()):
                self.assertIn(single, words)
            self.assertTrue(any("-a" in c.argv and "-z" in c.argv for c in first))
            self.assertEqual(len(first), len({c.identity() for c in first}))

        def test_option_ledger_matches_spellings_and_refusal(self):
            rows = [{"utility": "flagged", "option": "-z", "reason": "deliberate"}]
            case = Case("text", "flagged", ["-a", "-z"])
            self.assertIsNotNone(option_ledger(rows, case))
            self.assertIsNone(option_ledger(rows, Case("text", "flagged", ["-a"])))
            self.assertIsNotNone(option_ledger([{"utility": "x", "option": "--w"}],
                                               Case("text", "x", ["--w=3"])))
            _, (want, got) = self.pair("flagged", ["-z"])
            self.assertNotEqual(differences(want, got), ())
            self.assertTrue(got["status"] != 0 and not got["stdout"])

        def test_shrink_keeps_the_signature(self):
            case, (want, got) = self.pair("flagged", ["-a", "-b", "-z", "-c"])
            smaller, want2, got2 = shrink(self.runner, case, None, want, got, "loose")
            self.assertEqual(signature(want2, got2, "loose"), signature(want, got, "loose"))
            self.assertIn("-z", smaller.argv)
            self.assertLess(len(smaller.argv), 4)

        def test_main_end_to_end_with_recording(self):
            spec_dir = self.root / "specs"
            spec_dir.mkdir()
            (spec_dir / "spec_text.py").write_text(
                "from differential import Utility, Option\n"
                "UTILITIES = (Utility('flagged', options=(Option('-a'), Option('-z')), stdin=('text',)),\n"
                "             Utility('wrong'),)\n")
            pins = self.root / "pins.py"
            pins.write_text("\n" + PIN_BEGIN + '\nPINNED = r"""\n[]\n"""\n' + PIN_END + "\n")
            saved = PIN_FILE
            globals_ = globals()
            globals_["PIN_FILE"] = pins
            sys.path.insert(0, str(spec_dir))
            sys.modules.pop("spec_text", None)
            saved_specs = globals_.get("SPECS")
            globals_["SPECS"] = None
            try:
                import io
                import contextlib
                out = io.StringIO()
                with contextlib.redirect_stdout(out):
                    status = main([str(self.farm), "--domain", "text", "--budget", "singles",
                                   "--jobs", "1", "--record", "ledger", "--reason", "self-test",
                                   "--kind", "bug"])
                self.assertEqual(status, 1)
                text = out.getvalue()
                self.assertIn("FAIL", text)
                self.assertIn("text/wrong", text)
                rows = load_rows("ledger")
                self.assertTrue(rows)
                self.assertTrue(all(row["reason"] == "self-test" for row in rows))
                # With the divergences pinned, the same run passes.
                out = io.StringIO()
                with contextlib.redirect_stdout(out):
                    status = main([str(self.farm), "--domain", "text", "--budget", "singles", "--jobs", "1"])
                self.assertEqual(status, 0, out.getvalue())
                # A pinned row that starts agreeing fails and says so.
                self.script(self.farm / "wrong", "#!/bin/sh\nprintf right\n")
                out = io.StringIO()
                with contextlib.redirect_stdout(out):
                    status = main([str(self.farm), "--domain", "text", "--budget", "singles", "--jobs", "1"])
                self.assertEqual(status, 1)
                self.assertIn("agrees with the reference now", out.getvalue())
                # Regressions are recorded from agreements and rerun.
                out = io.StringIO()
                with contextlib.redirect_stdout(out):
                    main([str(self.farm), "--domain", "text", "--budget", "singles", "--jobs", "1",
                          "--utility", "flagged", "--record", "regression", "--no-pinned"])
                self.assertTrue(load_rows("regression"))
                self.assertTrue(load_rows("ledger"))
                self.assertIn("recorded", out.getvalue())
            finally:
                globals_["PIN_FILE"] = saved
                globals_["SPECS"] = saved_specs
                sys.path.remove(str(spec_dir))
                sys.modules.pop("spec_text", None)

        def test_every_domain_keeps_its_checks_and_grammars(self):
            """A grammar that stops being registered stops being tested, and
            says nothing while it happens. Assembling seven spec modules into
            one file made that possible: two of them spelled CHECKS, the later
            one won, and 138 util-linux cases quietly went. So every part of
            every registered domain is asked for by name here."""
            specs = globals().get("SPECS")
            if not specs:
                self.skipTest("the grammars are not inlined into this file")
            for domain, parts in specs.items():
                self.assertEqual(len(parts), 3,
                                 f"{domain} must register utilities, families and checks")
                spec = load_spec(domain)
                for part in ("UTILITIES", "FAMILIES", "CHECKS"):
                    self.assertIs(getattr(spec, part), parts[
                        ("UTILITIES", "FAMILIES", "CHECKS").index(part)],
                        f"{domain}.{part} is not what the registry holds")
                self.assertTrue(getattr(spec, "UTILITIES") or getattr(spec, "FAMILIES"),
                                f"{domain} has neither a utility nor a family")
                for check in getattr(spec, "CHECKS"):
                    self.assertTrue(callable(check), f"{domain} check is not callable")
            #       And the thing that actually went wrong: a section whose
            #       grammar is still spelled bare belongs to no domain, so
            #       nothing walks it. The registry cannot notice -- it is
            #       looking for the prefixed name -- but a bare one at module
            #       scope can only be a section that was not renamed.
            bare = [spelling for spelling in ("UTILITIES", "FAMILIES", "CHECKS")
                    if spelling in globals()]
            self.assertEqual(bare, [],
                             f"{bare} are spelled bare at module scope, so whatever "
                             f"they hold is registered to no domain and never runs")

        def test_every_lane_is_named_defined_and_described(self):
            """A lane that leaves the list stops running and says nothing,
            which is the same silence as a grammar that stops being
            registered. The three spellings must agree: the walk's list, the
            function it calls, and the line that says what it does."""
            import re
            runner = Path(__file__).resolve().parent / "run"
            if not runner.is_file():
                self.skipTest("test/run is not beside this file")
            text = runner.read_text()
            listed = re.search(r'^lanes="([^"]*)"', text, re.M)
            self.assertIsNotNone(listed, "test/run has no lanes= list")
            named = listed.group(1).split()
            defined = set(re.findall(r"^lane_(\w+)\(\)", text, re.M))
            described = set(re.findall(r'^\s*(\w+)\)\s+echo "', text, re.M))
            self.assertEqual([n for n in named if n not in defined], [],
                             "named in lanes= with no lane_<name> to run")
            self.assertEqual(sorted(defined - set(named)), [],
                             "a lane_<name> exists that lanes= never runs")
            self.assertEqual([n for n in named if n not in described], [],
                             "a lane nothing says the purpose of")

        def test_no_definition_in_this_file_shadows_another(self):
            """The same hazard from the other side. Assembling modules into
            one file lets a name arrive twice, and the later one wins in
            silence: that is how a second HARNESS_CHECKS made the engines
            benchmark unreachable. A function or class defined twice is
            always either dead text or a shadow, so neither is allowed."""
            import ast
            source = Path(__file__).resolve().read_text()
            lines = source.splitlines(keepends=True)
            seen, shadowed, repeated = {}, [], []
            for node in ast.parse(source).body:
                if not isinstance(node, (ast.FunctionDef, ast.ClassDef)):
                    continue
                text = "".join(lines[node.lineno - 1:node.end_lineno])
                if node.name in seen:
                    (repeated if seen[node.name] == text else shadowed).append(
                        f"{node.name} at line {node.lineno}")
                seen.setdefault(node.name, text)
            self.assertEqual(shadowed, [],
                             "defined twice with different bodies, so the first is "
                             "unreachable: " + ", ".join(shadowed))
            self.assertEqual(repeated, [],
                             "defined twice with the same body, which is dead text: "
                             + ", ".join(repeated))

        def test_tally_is_written_per_program(self):
            tally = self.root / "tally"
            spec_dir = self.root / "specs2"
            spec_dir.mkdir()
            (spec_dir / "spec_text.py").write_text(
                "from differential import Utility\nUTILITIES = (Utility('echoer'),)\n")
            sys.path.insert(0, str(spec_dir))
            sys.modules.pop("spec_text", None)
            old = os.environ.get("TEST_TALLY")
            os.environ["TEST_TALLY"] = str(tally)
            saved_specs = globals().get("SPECS")
            globals()["SPECS"] = None
            try:
                import io
                import contextlib
                with contextlib.redirect_stdout(io.StringIO()):
                    status = main([str(self.farm), "--domain", "text", "--budget", "singles",
                                   "--jobs", "1", "--no-pinned"])
                self.assertEqual(status, 0)
                self.assertRegex(tally.read_text(), r"text-echoer (\d+) \1\n")
            finally:
                globals()["SPECS"] = saved_specs
                if old is None:
                    del os.environ["TEST_TALLY"]
                else:
                    os.environ["TEST_TALLY"] = old
                sys.path.remove(str(spec_dir))
                sys.modules.pop("spec_text", None)

    suite = unittest.defaultTestLoader.loadTestsFromTestCase(Oracle)
    result = unittest.TextTestRunner(verbosity=1).run(suite)
    if os.environ.get("TEST_TALLY"):
        with open(os.environ["TEST_TALLY"], "a") as tally:
            passed = result.testsRun - len(result.failures) - len(result.errors)
            tally.write(f"differential-oracle {passed} {result.testsRun}\n")
    return 0 if result.wasSuccessful() else 1



#
#      The standalone programs folded in here, which --harness
#      names. They are not differential cases and none of them is
#      run by a plain invocation: each is a whole program that
#      happens to live in this file rather than in one of its own.
#
#          python3 test/differential.py --harness engines --binary a=A --binary b=B
#
#      sh test/run bench engines is the same thing with the words
#      spelled the way the rest of the benchmarks are.
#

ENGINES_DOC = """Matched multicall-engine throughput, with output verification before timing.

Pass identically built snapshots as repeated --binary LABEL=PATH arguments.
The first is the performance reference; GNU tools independently verify bytes
and statuses. Timings include process startup and output to a memory-backed
file, not just the assembly kernel. CPU affinity does not isolate its SMT
sibling. JSON also retains child CPU time to distinguish scheduling delays
from time spent executing. Use primitive benchmarks for small-call costs."""

def engines_arguments():
    parser = argparse.ArgumentParser(description=ENGINES_DOC)
    parser.add_argument("--binary", action="append", required=True,
                        metavar="LABEL=PATH")
    parser.add_argument("--cpu", type=int)
    parser.add_argument("--rounds", type=int, default=11)
    parser.add_argument("--bytes", type=int, default=4 * 1024 * 1024)
    parser.add_argument("--filter", default="")
    parser.add_argument("--suite", choices=("engines", "stack", "shell", "all"), default="engines")
    parser.add_argument("--time-reference", action="store_true",
                        help="include the installed reference tool in paired timings")
    parser.add_argument("--allow-invalid", action="append", default=[], metavar="LABEL",
                        help="report this historical binary's wrong outputs without timing them")
    parser.add_argument("--json", type=Path)
    args = parser.parse_args()
    if args.rounds < 3 or args.bytes < 1:
        parser.error("use at least three rounds and one input byte")
    binaries = {}
    for item in args.binary:
        label, separator, path = item.partition("=")
        if not separator or not label or label in binaries:
            parser.error("binary arguments need distinct nonempty LABEL=PATH pairs")
        binary = Path(path).resolve(strict=True)
        if not binary.is_file() or not os.access(binary, os.X_OK):
            parser.error(f"not an executable file: {binary}")
        binaries[label] = str(binary)
    if "reference" in binaries:
        parser.error("reference is reserved for the installed tool")
    if len(binaries) < 2 and not args.time_reference:
        parser.error("supply at least two binaries built with the same flags")
    if set(args.allow_invalid) - binaries.keys():
        parser.error("allow-invalid must name a supplied binary label")
    if args.cpu is not None:
        if not hasattr(os, "sched_setaffinity"):
            parser.error("CPU affinity is unavailable on this platform")
        os.sched_setaffinity(0, {args.cpu})
    return args, binaries


def engines_workloads(root, size, env):
    # Deterministic, non-uniform bytes with every byte value represented.
    block = bytes((i * 197 + (i >> 8)) & 255 for i in range(65536))
    raw = root / "bytes"
    raw.write_bytes((block * ((size + len(block) - 1) // len(block)))[:size])
    for name, flags in (
        ("base64", ["--base64"]), ("base64url", ["--base64url"]),
        ("base32", ["--base32"]), ("base32hex", ["--base32hex"]),
        ("base16", ["--base16"]), ("base2msbf", ["--base2msbf"]),
        ("base2lsbf", ["--base2lsbf"]),
    ):
        for wrap in (0, 76):
            encode = [*flags, f"-w{wrap}", str(raw)]
            yield f"{name}/encode/w{wrap}", "basenc", encode
            encoded = root / f"{name}-{wrap}"
            with encoded.open("wb") as output:
                subprocess.run(["basenc", *encode], stdout=output, env=env,
                               check=True, timeout=30)
            yield f"{name}/decode/w{wrap}", "basenc", [*flags, "-d", str(encoded)]
    for name, operands in (
        ("integer", ["1", "1000000"]),
        ("stride", ["-200000", "3", "200000"]),
        ("padded", ["-w", "1", "200000"]),
        ("decimal", ["0.00", ".25", "50000"]),
        ("formatted", ["-f", "%+08.2f", "0.00", ".25", "50000"]),
        ("descending", ["1000000", "-1", "1"]),
        ("negative", ["-1000000", "-1"]),
        ("literal", ["-f", "row=%%[%+012.3f]", "-1000", ".125", "1000"]),
    ):
        yield f"seq/{name}", "seq", operands
    log = root / "kernel-log"
    with log.open("wb") as output:
        for i in range(32768):
            # Avoid GNU's zero-as-unset previous-timestamp policy; this row
            # measures formatting, not that unrelated first-delta difference.
            output.write(b"<6>[%5d.%06d] payload %05d\n" %
                         (1 + i // 1000, (i % 1000) * 1000, i))
    for name, flags in (("timestamp", []), ("delta", ["-d"]), ("json", ["-J"])):
        yield f"dmesg/{name}", "dmesg", [*flags, "-F", str(log)]
    # Exercise the real escaping consumers too: their selected categories
    # differ from dmesg and the all-categories primitive microbenchmark.
    uuids = [(f"bad\\value\x1b{i:06d}" if i % 4 == 0 else
              f"{i:08x}-1234-4234-8234-{i:012x}") for i in range(2048)]
    for name, flags in (("raw", ["-r"]), ("json", ["-J"])):
        yield f"uuidparse/{name}", "uuidparse", [*flags, *uuids]


def engines_stack_workloads(root, size):
    records = root / "records"
    count = max(1, size // 16)
    with records.open("wb") as output:
        for i in range(count):
            output.write((f"{'alpha' if i % 3 else 'beta'}:{i % 1000:03d}:"
                          f"{'needle' if i % 17 == 0 else 'plain'}\n").encode())
    groups = root / "groups"
    groups.write_bytes((b"ab" * 32 + b"\n" + b"ac" * 32 + b"\n") * max(1, count // 10))
    scripts = {
        "parse": ': # parser token stream\n' * 100_000 + 'printf "done\\n"\n',
        "loop": 'i=0; while [ "$i" -lt 300000 ]; do i=$((i+1)); done; printf "%s\\n" "$i"',
        "parameter": 'i=0; x=abcdefghijklmnop; while [ "$i" -lt 100000 ]; do a=${x#?}; b=${x%?}; c=${#x}; i=$((i+1)); done; printf "%s:%s:%s:%s\\n" "$a" "$b" "$c" "$i"',
        "function": 'f() { :; }; i=0; while [ "$i" -lt 300000 ]; do f; i=$((i+1)); done; printf "%s\\n" "$i"',
        "redefine": 'i=0; while [ "$i" -lt 100000 ]; do f() { :; }; i=$((i+1)); done; f; printf "%s\\n" "$i"',
    }
    for name, text in scripts.items():
        script = root / (name + ".sh")
        script.write_text(text + "\n")
        yield "shell/" + name, "bash", [str(script)], None
    for name, tool, operands, source in (
        ("cat", "cat", [records], None),
        ("cat-number", "cat", ["-n", records], None),
        ("cat-visible", "cat", ["-v", records], None),
        ("wc-lines", "wc", ["-l"], records),
        ("wc-words", "wc", ["-w"], records),
        ("grep-literal", "grep", ["-c", "needle", records], None),
        ("grep-group8", "grep", ["-Ec", "(ab){8}", groups], None),
        ("grep-group32", "grep", ["-Ec", "(ab){32}", groups], None),
        ("cut-field", "cut", ["-d:", "-f2", records], None),
        ("cut-trim-first", "cut", ["-c2-", records], None),
        ("cut-prefix", "cut", ["-c1-5", records], None),
        ("cut-suffix", "cut", ["-c7-", records], None),
        ("tr-case", "tr", ["a-z", "A-Z"], records),
        ("tr-delete", "tr", ["-d", "a"], records),
        ("tr-squeeze", "tr", ["-s", "a-z"], records),
        ("sed-literal", "sed", ["s/alpha/omega/g", records], None),
        ("sed-capture", "sed", ["-E", r"s/(alpha):([0-9]+)/\2:\1/g", records], None),
        ("awk-fields", "awk", ["-F:", "{s += $2} END {print s}", records], None),
        ("sort", "sort", [records], None),
        ("uniq", "uniq", ["-c", records], None),
        ("head", "head", ["-n", "1000", records], None),
        ("tail", "tail", ["-n", "1000", records], None),
        ("rev", "rev", [records], None),
        ("base64", "base64", ["-w0", records], None),
        ("base32", "base32", ["-w0", records], None),
        ("od-hex", "od", ["-An", "-tx1", records], None),
        ("hexdump", "hexdump", ["-C", records], None),
        ("cksum", "cksum", [records], None),
        ("sha256sum", "sha256sum", [records], None),
    ):
        yield name, tool, [str(value) for value in operands], source
    left, right = root / "left", root / "right"
    left.write_text("".join(f"{i:07d}\n" for i in range(0, count, 2)))
    right.write_text("".join(f"{i:07d}\n" for i in range(0, count, 3)))
    for tool in ("comm", "paste"):
        yield tool, tool, [str(left), str(right)], None
    left.write_text("".join(f"{i:07d} left-{i % 97:02d}\n" for i in range(count // 2)))
    right.write_text("".join(f"{i:07d} right-{i % 89:02d}\n" for i in range(count // 2)))
    yield "join", "join", [str(left), str(right)], None


def engines_selected_workloads(root, size, env, suite):
    if suite in ("engines", "all"):
        for name, tool, operands in engines_workloads(root, size, env):
            yield name, tool, operands, None
    if suite in ("stack", "all"):
        yield from engines_stack_workloads(root, size)
    if suite in ("shell", "all"):
        yield from engines_shell_workloads(root, size, legacy=suite != "all")


def engines_shell_workloads(root, size, legacy=True):
    """Shell-owned work: inputs are generated outside every timed invocation.

    Keep the five historical stack controls at their original scale. New
    repeated-body cases scale with --bytes; filesystem/process cases have
    their own caps so a reference shell remains practical to time.
    """
    if legacy:
        for row in engines_stack_workloads(root, size):
            if row[0].startswith("shell/"):
                yield row
    count = max(1000, min(100000, size // 64))
    processes = max(16, min(256, count // 128))
    sink = root / "shell-redirection"
    glob_root = root / "shell-glob"
    glob_root.mkdir(exist_ok=True)
    for i in range(128):
        (glob_root / f"entry-{i:03d}.txt").touch()
    sourced = root / "shell-sourced.sh"
    sourced.write_text('source_value=$((source_value+1))\n')

    def loop(body, setup="", result='printf "%s\\n" "$i"', turns=count):
        return (f"{setup}\ni=0\nwhile [ \"$i\" -lt {turns} ]; do\n"
                f"{body}\ni=$((i+1))\ndone\n{result}\n")

    scripts = {
        "arithmetic": loop('((a=(a*33+i)^7))', 'a=1',
                           'printf "%s:%s\\n" "$a" "$i"'),
        "scalar-short": loop(': "$x" "$long_variable_name" "prefix${x}suffix"',
                             'x=abc; long_variable_name=xyz'),
        "scalar-long": loop(': "$x" "$long_variable_name" "prefix${x}suffix"',
                            'x=' + 'abcdefgh' * 128 + '\nlong_variable_name=$x'),
        "parameter-mix": loop('a=${x#prefix}; b=${x%suffix}; c=${x//ab/CD}; d=${x:2:8}',
                              'x=prefix' + 'abcd' * 24 + 'suffix',
                              'printf "%s:%s:%s:%s:%s\\n" "$a" "$b" "$c" "$d" "$i"'),
        "fields": loop('set -- $x; n=$((n+$#))',
                       "x=' alpha  beta\tgamma\n delta '; n=0",
                       'printf "%s:%s\\n" "$n" "$i"'),
        "ifs-fields": loop('set -- $x; n=$((n+$#))',
                           "IFS=:,; x='alpha::beta,gamma:delta'; n=0",
                           'printf "%s:%s\\n" "$n" "$i"'),
        "positional": loop('f "" "a b" "*" z',
                           'n=0; f() { for word in "$@"; do n=$((n+${#word}+1)); done; }',
                           'printf "%s:%s\\n" "$n" "$i"'),
        "local-nameref": loop('f "$i"',
                              'f() { local x=$1; local -n r=x; r=$((r+1)); result=$r; }',
                              'printf "%s:%s\\n" "$result" "$i"'),
        "array-indexed": loop('((a[i%3]+=i))', 'a=(1 2 3)',
                              'printf "%s:%s:%s:%s\\n" "${a[0]}" "${a[1]}" "${a[2]}" "$i"'),
        "array-associative": loop('m[alpha]=$i; x=${m[alpha]}; y=${m[long_key]}',
                                  'declare -A m=([alpha]=1 [long_key]=value)',
                                  'printf "%s:%s:%s\\n" "$x" "$y" "$i"'),
        "builtin-format": loop('printf -v x "%08d:%s" "$i" abc; [ "$x" != "" ]',
                               result='printf "%s:%s\\n" "$x" "$i"'),
        "case-pattern": loop('case abcdef in a*e?) n=$((n+1));; *) n=0;; esac',
                             'n=0', 'printf "%s:%s\\n" "$n" "$i"'),
        "regex-condition": loop('if [[ $x =~ ^([a-z]+):([0-9]+)$ ]]; then n=$((n+1)); fi',
                                'x=alpha:123; n=0',
                                'printf "%s:%s:%s\\n" "$n" "${BASH_REMATCH[2]}" "$i"'),
        "glob": loop(f'set -- "{glob_root}"/entry-0[0-9]?.txt; n=$((n+$#))',
                     'n=0', 'printf "%s:%s\\n" "$n" "$i"', turns=min(count, 2000)),
        "brace": loop('set -- item{01..64}; n=$((n+$#))', 'n=0',
                      'printf "%s:%s\\n" "$n" "$i"', turns=min(count, 4000)),
        "read-lines": 'n=0; while IFS= read -r line; do n=$((n+${#line})); done\nprintf "%s\\n" "$n"\n',
        "mapfile": 'mapfile -t rows; printf "%s:%s\\n" "${#rows[@]}" "${rows[0]}"\n',
        "command-substitution": loop('x=$(printf "%s" "$i")',
                                     result='printf "%s:%s\\n" "$x" "$i"', turns=processes),
        "pipeline": loop('printf "one\\ntwo\\n" | { n=0; while IFS= read -r x; do n=$((n+1)); done; printf "%s\\n" "$n"; }',
                         turns=processes),
        "subshell": loop('( : )', turns=processes),
        "background-wait": loop('( : ) & wait', turns=processes),
        "redirect": loop(f': > "{sink}"', turns=min(count, 2000)),
        "source": loop(f'. "{sourced}"', 'source_value=0',
                       'printf "%s:%s\\n" "$source_value" "$i"', turns=min(count, 2000)),
        "trap": loop('kill -USR1 $$', 'n=0; trap \'n=$((n+1))\' USR1',
                     'printf "%s:%s\\n" "$n" "$i"', turns=min(count, 2000)),
    }
    scripts["parse-arguments"] = (': alpha beta gamma long_variable_name delta\n' * count +
                                  'printf "done\\n"\n')
    scripts["parse-quotes"] = (': \'single quoted\' "double quoted" escaped\\ word "${missing:-fallback}"\n' * count +
                               'printf "done\\n"\n')
    scripts["parse-grammar"] = ('if :; then :; elif false; then :; else :; fi\n' * count +
                                'printf "done\\n"\n')
    scripts["parse-heredoc"] = ('f() { : <<\'END\'\n$literal \\ text\nEND\n}\n' * min(count, 4000) +
                               'f; printf "done\\n"\n')
    scripts["alias"] = ("shopt -s expand_aliases\nalias hit=':'\n" +
                        'hit alpha beta\n' * count + 'printf "done\\n"\n')
    inputs = root / "shell-input"
    inputs.write_bytes(b"alpha beta\\gamma\n" * count)
    yield "shell/startup", "bash", ["-c", ":"], None
    for name, script in scripts.items():
        path = root / ("shell-" + name + ".sh")
        path.write_text(script)
        source = inputs if name in ("read-lines", "mapfile") else None
        yield "shell/" + name, "bash", [str(path)], source


def engines_expired(signum, frame):
    raise TimeoutError("benchmark process exceeded 60 seconds")


def engines_invoke(binary, tool, operands, output, env, timed=False, source=None, expected=None):
    output.seek(0)
    output.truncate()
    input_file = open(source, "rb") if source else None
    before = resource.getrusage(resource.RUSAGE_CHILDREN) if timed else None
    started = time.perf_counter_ns()
    try:
        with subprocess.Popen([tool, *operands], executable=binary, stdout=output,
                              stdin=input_file or subprocess.DEVNULL,
                              stderr=subprocess.PIPE, env=env, start_new_session=True) as process:
            # communicate(timeout) also calls wait(timeout) after pipe EOF,
            # which can add a 1 ms polling sleep. A signal deadline lets
            # both pipe draining and child reaping remain blocking.
            previous_alarm = signal.signal(signal.SIGALRM, engines_expired)
            signal.setitimer(signal.ITIMER_REAL, 60)
            try:
                _, errors = process.communicate()
            except TimeoutError:
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                process.communicate()
                raise
            finally:
                signal.setitimer(signal.ITIMER_REAL, 0)
                signal.signal(signal.SIGALRM, previous_alarm)
    finally:
        if input_file:
            input_file.close()
    elapsed = (time.perf_counter_ns() - started) / 1e6
    if timed:
        if process.returncode or errors:
            raise RuntimeError((tool, operands, process.returncode, errors))
        after = resource.getrusage(resource.RUSAGE_CHILDREN)
        cpu_ms = 1000 * (after.ru_utime + after.ru_stime -
                         before.ru_utime - before.ru_stime)
        output.seek(0)
        digest = hashlib.file_digest(output, "sha256").hexdigest()
        if digest != expected[1]:
            raise RuntimeError((tool, operands, "timed output mismatch", digest, expected[1]))
        return elapsed, cpu_ms
    output.seek(0)
    digest = hashlib.file_digest(output, "sha256").hexdigest()
    return process.returncode, digest, errors


def harness_engines():
    args, binaries = engines_arguments()
    env = dict(os.environ, LC_ALL="C", TZ="UTC0", ENV="/dev/null", BASH_ENV="/dev/null")
    labels = [*binaries, *(["reference"] if args.time_reference else [])]
    result = {
        "binaries": {label: {"path": path, "sha256": hashlib.sha256(
            Path(path).read_bytes()).hexdigest()} for label, path in binaries.items()},
        "cpu": args.cpu, "input_bytes": args.bytes, "rounds": args.rounds,
        "qualification": "End-to-end wall time; affinity is not SMT isolation",
        "suite": args.suite,
        "verification": "Exact status, stderr and stdout SHA-256 on every run; hashing is outside timing",
        "references": {},
        "rows": [],
    }
    print("case\t" + "\t".join(f"{label} ms" for label in labels), flush=True)
    with tempfile.TemporaryDirectory(prefix="moonwater-engine-bench-") as work:
        root = Path(work)
        output_file = (os.fdopen(os.memfd_create("moonwater-engine-output"), "w+b")
                       if hasattr(os, "memfd_create") else tempfile.TemporaryFile(dir=root))
        with output_file as output:
            for name, tool, operands, source in engines_selected_workloads(root, args.bytes, env, args.suite):
                if args.filter not in name:
                    continue
                reference = shutil.which(tool)
                if not reference:
                    raise SystemExit(f"missing reference tool: {tool}")
                if tool not in result["references"]:
                    version = subprocess.run([reference, "--version"], stdout=subprocess.PIPE,
                                             stderr=subprocess.STDOUT, env=env, timeout=5).stdout
                    result["references"][tool] = {"path": reference, "sha256": hashlib.sha256(
                        Path(reference).read_bytes()).hexdigest(), "version": version.decode(errors="replace").splitlines()[0]}
                expected = engines_invoke(reference, tool, operands, output, env, source=source)
                if expected[0] or expected[2]:
                    raise RuntimeError((name, "reference failed", expected))
                invalid = {}
                current = dict(binaries, **({"reference": reference} if args.time_reference else {}))
                for label, binary in binaries.items():
                    actual = engines_invoke(binary, tool, operands, output, env, source=source)
                    if actual != expected:
                        if label in args.allow_invalid:
                            invalid[label] = {"status": actual[0], "sha256": actual[1],
                                              "stderr": actual[2].decode(errors="replace")}
                            continue
                        raise RuntimeError((name, label, "output/status mismatch",
                                            actual, expected))
                valid = [label for label in labels if label not in invalid]
                samples = {label: [] for label in valid}
                cpu_samples = {label: [] for label in valid}
                for trial in range(args.rounds + 2):
                    if not valid:
                        break
                    offset = trial % len(valid)
                    order = valid[offset:] + valid[:offset]
                    if (trial // len(valid)) & 1:
                        order = order[::-1]
                    for label in order:
                        elapsed, cpu_ms = engines_invoke(current[label], tool, operands,
                                                 output, env, timed=True, source=source,
                                                 expected=expected)
                        if trial >= 2:
                            samples[label].append(elapsed)
                            cpu_samples[label].append(cpu_ms)
                medians = {label: statistics.median(values)
                           for label, values in samples.items()}
                result["rows"].append({
                    "case": name, "median_ms": medians, "samples_ms": samples,
                    "cpu_median_ms": {label: statistics.median(values)
                                      for label, values in cpu_samples.items()},
                    "cpu_samples_ms": cpu_samples,
                    "applet": tool, "arguments": operands,
                    "stdin_sha256": hashlib.sha256(source.read_bytes()).hexdigest() if source else None,
                    "invalid": invalid,
                    "ratio_to_first": {label: value / medians[labels[0]]
                                       if labels[0] in medians else None
                                       for label, value in medians.items()},
                    "paired_ratio_to_first": {label: [value / samples[labels[0]][i]
                        for i, value in enumerate(values)] for label, values in samples.items()}
                        if labels[0] in samples else {},
                    "verified_sha256": expected[1],
                })
                print(name + "\t" + "\t".join(f"{medians[label]:.3f}"
                      if label in medians else "INVALID"
                      for label in labels), flush=True)
                if args.json:
                    args.json.write_text(json.dumps(result, indent=2) + "\n")
    if not result["rows"]:
        raise SystemExit("filter selected no workloads")
    if args.json:
        args.json.write_text(json.dumps(result, indent=2) + "\n")


def harness_engines_main(argv):
    """--harness engines ARGS, from harness_main: the engine benchmark.

    The other folded programs read the words they were given; this one was a
    command of its own and parses sys.argv, so the words go back there under
    a program name that says how it was reached.
    """
    sys.argv = ["%s --harness engines" % sys.argv[0], *argv]
    return harness_engines() or 0

