        ("BEGIN { print (\"PATH\" in ENVIRON), (\"NOSUCH_VAR\" in ENVIRON), ENVIRON[\"LC_ALL\"], (length(ENVIRON[\"HOME\"]) > 0) }",),
        ("BEGIN { for (k in ENVIRON) n++; print (n > 3) }",),
        ("--", "{ print $0 }", "one"),
        ("--", "BEGIN { print \"dd\" }"),
        ("{ print FILENAME, $0 }", "-"),
        ("{ print FILENAME, FNR, NR }", "one", "grid"),
