        ("{ $1 = \"\"; sub(/^ /, \"\"); print }", "grid"),
        ("{ $2 = \"a\"; gsub(/a/, \"X\"); print }", "grid"),
        ("{ $3 = \"z\"; $0 = $0 \"!\"; print; print NF }", "grid"),
