def text_regex_pool(seed, atoms, count):
    """count distinct patterns of one to three atoms, some anchored."""
    rng = random.Random(seed)
    pool = []
    seen = set()
    while len(pool) < count:
        pattern = "".join(rng.choice(atoms) for _ in range(rng.randint(1, 3)))
        if rng.random() < 0.25:
            pattern = "^" + pattern
        if rng.random() < 0.25:
            pattern += "$"
        if pattern in seen:
            continue
        seen.add(pattern)
        pool.append(pattern)
    return pool


