def text_cut_valid(argv):
    lists = 0
    for word in argv:
        if word in ("-b", "-c", "-f", "-F") or word.startswith(("--bytes", "--characters", "--fields")) \
                or (word.startswith(("-b", "-c", "-f", "-F")) and len(word) > 2 and not word.startswith("--")):
            lists += 1
    return lists == 1


