def harness_main(argv):
    if not argv or argv[0] not in HARNESS_CHECKS:
        print("harness: one of " + " ".join(HARNESS_CHECKS), file=sys.stderr)
        return 2
    return HARNESS_CHECKS[argv[0]](argv[1:])



def harness_entry():
    sys.exit(harness_main(sys.argv[1:]))

